package com.earthtrip.platform.adapter.out.persistence.integration;
import com.earthtrip.platform.application.port.out.IntegrationStorePort;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="trip_calendar_syncs")class CalendarSyncJpaEntity{@Id @Column(name="trip_id",length=36)String tripId;@Column(name="connection_id",length=36)String connectionId;@Column(name="scope_config",columnDefinition="JSON")String scope;@Column(name="status",length=30)String status;@Column(name="created_by",length=36)String createdBy;@Column(name="created_at")Instant createdAt;@Column(name="updated_at")Instant updatedAt;@Version @Column(name="version")long version;protected CalendarSyncJpaEntity(){}CalendarSyncJpaEntity(IntegrationStorePort.CalendarRecord r,String s){tripId=r.tripId().toString();createdBy=r.createdBy().toString();createdAt=r.createdAt();apply(r,s);}void apply(IntegrationStorePort.CalendarRecord r,String s){connectionId=r.connectionId().toString();scope=s;status=r.status();updatedAt=r.updatedAt();}IntegrationStorePort.CalendarRecord record(Map<String,Object>s){return new IntegrationStorePort.CalendarRecord(UUID.fromString(tripId),UUID.fromString(connectionId),s,status,UUID.fromString(createdBy),createdAt,updatedAt,version);}}
